      'MOTHER-9의 감시망을 피해 움직일수록 도시가 오히려 파티를 배려하는 듯한 이상 현상이 나타났다. 신호등이 한 박자 빨리 바뀌고, 추적 드론은 결정적인 순간마다 시야를 돌렸다. 누군가 중앙 AI 내부에서 파티를 돕고 있었다. 하지만 그 도움의 패턴은 삭제된 48시간 동안 파티가 남겼던 행동 기록과 정확히 일치했다.',
