      '숲의 심장에 가까워질수록 밤하늘의 별자리가 지상 나뭇가지와 같은 모양을 만들었다. 나무 하나가 부러지면 별 하나가 희미해졌고, 별 하나가 떨어지면 땅속 뿌리가 뜨거워졌다. 숲과 하늘 중 어느 쪽이 다른 쪽을 따라 하고 있는지 알 수 없었다.',
