      subtitle:'셴 시티의 수련에서 쉬버링 산의 진실까지. 동료가 늘수록 선택의 무게도 커진다.',
      intro:'첫 여정을 끝낸 기사와 작은 공주는 다음 챔피언을 찾아 셴 시티로 향한다. 무술가들의 도시에서 시작된 여행은 장난스러운 요정 때문에 작아진 여관, 지하 깊은 던전 왕국, 살인사건과 편견에 얼어붙은 쉬버링 산으로 이어진다. 각 월드에서 얻은 동료와 약속은 다음 월드에서 실제 도움이나 부담으로 되돌아온다.',
      acts:['월드 5 · 셴 시티','월드 6 · 여관...?','월드 7 · 던전 왕국','월드 8 · 쉬버링 산','두 번째 원정의 대가'],
