    {goal:'월드 5~8의 챔피언과 약속을 정리하고 라 제국에서 벌어질 더 큰 충돌에 대비한다',place:'설산을 내려가는 국경로',reveal:'침략자의 영향은 이제 개별 세계의 사건을 넘어 국가 간 정치와 난민 문제로 번지고 있다',stakes:'2부에서 만든 동료 관계가 3부의 저항군 지원과 엔딩 문장에 영향을 준다'}
